The claims for $r = 0$ have already been shown in \cite[Theorem 1(e)]{Di2022}. We thus only
	discuss the cases $r = 1, 2, \ldots$ here. To this end, we first recall from \cite[Theorem 1]{Di2022} that
	\begin{equation}
		\label{eq:def-phinew}
		\phi_{\mathrm D}(w, t) 
			= (-1)^{\lfloor \alpha \rfloor} \frac{\sin \alpha \pi}{\pi} \mathrm e^{wq_{\mathrm D}}
				\int_a^t y^{(\lceil \alpha \rceil)}(\tau) \exp\left(-(t-\tau) \mathrm e^w\right) \mathrm d\tau
	\end{equation}
	holds for any fixed $t \in [a, a+T]$. This implies, in particular, that $\phi_{\mathrm D}(w, a) = 0$ for all $w$,
	and so the claims clearly hold in the case $t = a$.
	
	For $t > a$, an application of Leibniz' rule to \eqref{eq:def-phinew} shows that
	\begin{align*}
		\frac{\partial^r \phi_{\mathrm D}}{\partial w^r} (w, t)  
		&=  (-1)^{\lfloor \alpha \rfloor} \frac{\sin \alpha \pi}{\pi} \\
		& \phantom{{}={}} \quad \times \sum_{s=0}^r \binom{r}{s} q_{\mathrm D}^{r-s} e^{wq_{\mathrm D}}
				\int_a^t y^{(\lceil \alpha \rceil)}(\tau) \frac{\partial^s}{\partial w^s} 
					\exp\left(-(t-\tau) \mathrm e^w\right) \mathrm d\tau	
	\end{align*}
	which, upon setting
	\[
		c = \frac{|\sin \alpha \pi|}{\pi} \| y^{(\lceil \alpha \rceil)} \|_{L_\infty[a, a+T]} < \infty,
	\]
	implies for all $w \in \mathbb R$ that
	\begin{align}
		\nonumber
		\left| \frac{\partial^r \phi_{\mathrm D}}{\partial w^r} (w, t) \right|
		& \le c \sum_{s=0}^r \binom{r}{s} q_{\mathrm D}^{r-s} e^{wq_{\mathrm D}}
				\int_a^t \frac{\partial^s}{\partial w^s} 
					\exp\left(-(t-\tau) \mathrm e^w\right) \mathrm d\tau \\
		& = c \sum_{s=0}^r \binom{r}{s} q_{\mathrm D}^{r-s} e^{wq_{\mathrm D}}
				\frac{\partial^s}{\partial w^s} 
					\int_a^t \exp\left(-(t-\tau) \mathrm e^w\right) \mathrm d\tau 
					\label{eq:l2a} \\
		& = c \sum_{s=0}^r \binom{r}{s} q_{\mathrm D}^{r-s} e^{wq_{\mathrm D}}
				\frac{\partial^s}{\partial w^s} 
					\left[ \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right) \right].
			\nonumber
	\end{align}
	For the last factor in each summand, we can again use Leibniz' rule and find
	\begin{eqnarray}
		\nonumber
		\lefteqn{\frac{\partial^s}{\partial w^s} 
			\left[ \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right) \right] } \\
		& = & \sum_{\sigma=1}^s \binom{s}{\sigma} (-1)^{s-\sigma} \mathrm e^{-w} 
				\frac{\partial^\sigma}{\partial w^\sigma} \exp \left( - (t-a) \mathrm e^w \right) 
				\label{eq:l2b} \\
		& & \nonumber
		{} + (-1)^s \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right) \\
		& = & \nonumber
			\sum_{\sigma=1}^s \binom{s}{\sigma} (-1)^{s-\sigma} J_\sigma(w) + (-1)^s J_0(w)
	\end{eqnarray}
	with
	\[ 
		J_0(w) = \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right)
	\]
	and
	\[
		J_\sigma(w) = \mathrm e^{-w} \frac{\partial^\sigma}{\partial w^\sigma} \exp \left( - (t-a) \mathrm e^w \right) 
		\quad (s = 1, 2, 3, \ldots).
	\]
	It is then immediately clear that 
	\[
		|J_0(w)| \le \mathrm e^{-w} \mbox{ for all } w,
	\]
	so 
	\begin{equation}
		\label{eq:l2c}
		\lim_{w \to \infty} \mathrm e^w |J_0(w)| \le 1 
	\end{equation}
	and, by de l'Hospital's rule,
	\begin{equation}
		\label{eq:l2d}
		\lim_{w \to -\infty} J_0(w) = t - a.
	\end{equation}
	Moreover, a straightforward mathematical induction yields for $\sigma = 1, 2, 3, \ldots$ that there
	exist polynomials $\pi_{\sigma-1}$ of degree $\sigma-1$ (whose coefficients may depend on $t-a$
	but whose precise form is not relevant for our purposes) such that
	\[
		J_\sigma(w) =\exp(-(t-a) \mathrm e^w) \pi_{\sigma-1}(\mathrm e^w).
	\]
	Denoting the polynomials $\pi_{\sigma-1}$ by $\pi_{\sigma-1}(z) = \sum_{\rho = 0}^{\sigma-1} \psi_\rho z^\rho$, 
	we conclude
	\[
		J_\sigma(w) = \exp(-(t-a) \mathrm e^w) \sum_{\rho = 0}^{\sigma-1} \psi_\rho \mathrm e^{\rho w}
			=  \sum_{\rho = 0}^{\sigma-1} \psi_\rho \exp ( \rho w - (t-a) \mathrm e^w ) .
	\]
	Thus,
	\begin{equation}
		\label{eq:l2e}
		\lim_{w \to -\infty} |J_\sigma(w)| 
		\le \lim_{w \to -\infty} \sum_{\rho = 0}^{\sigma-1} | \psi_\rho | \exp ( \rho w - (t-a) \mathrm e^w ) 
		= |\psi_0|
	\end{equation}
	and
	\begin{equation}
		\label{eq:l2f}
		\lim_{w \to \infty} \mathrm e^w |J_\sigma(w)|
		\le \lim_{w \to \infty} \sum_{\rho = 0}^{\sigma-1} | \psi_\rho | \exp ( (\rho + 1) w - (t-a) \mathrm e^w ) = 0
	\end{equation}
	because (since we only need to deal with those values of $t$ for which $t > a$) the argument of each of the
	exponential functions is less than $-2 w$ for sufficiently large $w$.
	Plugging \eqref{eq:l2c} and \eqref{eq:l2f} into \eqref{eq:l2b}, we then derive
	\[
		\frac{\partial^s}{\partial w^s} 
			\left[ \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right) \right] 
			= O(\mathrm e^{-w})
			\mbox{ for } w \to \infty,
	\]
	and inserting \eqref{eq:l2d} and \eqref{eq:l2e} into \eqref{eq:l2b}, we find
	\[
		\frac{\partial^s}{\partial w^s} 
			\left[ \mathrm e^{-w} \left( 1 - \exp \left( - (t-a) \mathrm e^w \right) \right) \right] 
			= O(1)
			\mbox{ for } w \to - \infty.
	\]
	The two claims of the Lemma then follow upon combining these two relations with eq.\ \eqref{eq:l2a}.

A careful inspection of this proof reveals that the implied constants in the $O$-terms of the two claims
	can be chosen independently of the value of $t \in [a, a+T]$, so the estimates of Lemma \ref{lem:asymp-phi}
	hold uniformly for all $t \in [a, a+T]$.

\label{lem:r-ode}
	Assume that the grid $\{ t_n : n = 0, 1, \ldots, N \}$ is uniform, i.e.\ that $t_n = a + n h$ with 
	$h = T/N$.
	If $y \in C^{\lceil \alpha \rceil+1} [a, a+T]$ and the differential equations are solved by the backward Euler method, then
	\[
		| R^{\mathrm{ODE}}_{\alpha, K, n}(y) | \le C(K) t_n h \le C(K) T h
	\]
	with 
	\begin{align*}
		C(K) &=  \frac{|\sin \alpha \pi |} {2 \pi} \mathrm e^{x_{K,K}^{\mathrm{GLa}} q_{\mathrm D} / (1 - q_{\mathrm D})} \\
		 	&  \qquad \times
		 		\left( \left\| y^{(\lceil \alpha \rceil +1)}(t) \right\|_{L_\infty[a, a+T]}
			+ 2 \mathrm e^{x_{K,K}^{\mathrm{GLa}} / (1 - q_{\mathrm D})}
				 \left\| y^{(\lceil \alpha \rceil)}(t) \right\|_{L_\infty[a, a+T]} \right).
	\end{align*}
